import math
class Solution:
    def minimumSplits(self, nums: List[int]) -> int:
        n = len(nums)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(n):
            g = 0
            for j in range(i, -1, -1):
                g = math.gcd(g, nums[j])
                if g == 1:
                    break
                dp[i + 1] = min(dp[i + 1], dp[j] + 1)
        return dp[n]

