class Solution {
    int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
    public int minimumSplits(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            int g = 0;
            for (int j = i; j >= 0; j--) {
                g = gcd(g, nums[j]);
                if (g == 1) break;
                dp[i + 1] = Math.min(dp[i + 1], dp[j] + 1);
            }
        }
        return dp[n];
    }
}

