    const dp = Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        let g = 0;
        for (let j = i; j >= 0; j--) {
            g = gcd(g, nums[j]);
            if (g === 1) break;
            dp[i + 1] = Math.min(dp[i + 1], dp[j] + 1);
        }
    }
    return dp[n];
};

